package io.portfolio.erp.service;
import io.portfolio.erp.domain.AssetChangeRequest; import io.portfolio.erp.mapper.AssetMapper; import org.junit.Test; import static org.junit.Assert.*; import static org.mockito.Mockito.*;
public class AssetServiceTest { @Test public void approvalAppliesRequestedAssetValues(){AssetMapper m=mock(AssetMapper.class);AssetChangeRequest r=new AssetChangeRequest();r.setRequestId(1L);r.setAssetNo("AST-1");r.setRequestStatus("PENDING");r.setRequestedDepartment("Sales");r.setRequestedOwner("User");r.setRequestedLocation("HQ");when(m.findRequest(1L)).thenReturn(r);when(m.updateRequestDecision(eq(1L),eq("APPROVED"),eq("admin"),anyString())).thenReturn(1);AssetService s=new AssetService(m);s.decide(1L,true,"admin");verify(m).applyAssetChange("AST-1","Sales","User","HQ");} }
